import openpyxl
wb = openpyxl.load_workbook('sales_data.xlsx')
for ws in wb.worksheets:
    print(f"Sheet: {ws.title}, dims: {ws.dimensions}, max_row={ws.max_row}, max_col={ws.max_column}")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 8)):
        print([c.coordinate for c in row], [c.value for c in row])

import importlib, subprocess, shutil, sys
mods = ["openpyxl", "pandas", "xlsxwriter", "xlrd", "lxml", "numpy", "zipfile", "xml.etree.ElementTree"]
for m in mods:
    try:
        importlib.import_module(m)
        print(m, "OK")
    except Exception as e:
        print(m, "MISSING", type(e).__name__)
print("python:", sys.version)
for exe in ["soffice", "libreoffice", "python3"]:
    print(exe, "->", shutil.which(exe))
r = subprocess.run([shutil.which("soffice") or "soffice", "--version"], capture_output=True, text=True)
print("soffice out:", r.stdout, r.stderr)

